import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { PlanType } from "@/types";

// ── useCheckout ──────────────────────────────────────────────────
// Initiates a Stripe Checkout session for the given plan + billing cycle.
// On success, redirects the browser to Stripe-hosted checkout.

export function useCheckout() {
  return useMutation({
    mutationFn: async ({
      plan,
      billingCycle,
    }: {
      plan: Exclude<PlanType, "free">;
      billingCycle: "monthly" | "annual";
    }) => {
      const { data, error } = await supabase.functions.invoke(
        "stripe-checkout",
        {
          body: { plan, billing_cycle: billingCycle },
        }
      );

      if (error) {
        throw new Error(
          error.message || "Failed to start checkout. Please try again."
        );
      }

      if (!data?.url) {
        throw new Error("No checkout URL returned from server.");
      }

      return data.url as string;
    },
    onSuccess: (url) => {
      window.location.href = url;
    },
    onError: (error: unknown) => {
      const message =
        error instanceof Error ? error.message : "Checkout failed.";
      toast.error(message);
    },
  });
}

// ── useCustomerPortal ────────────────────────────────────────────
// Opens the Stripe Customer Portal so users can manage their subscription,
// payment method, and invoices.

export function useCustomerPortal() {
  return useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke("stripe-portal");

      if (error) {
        throw new Error(
          error.message || "Failed to open billing portal. Please try again."
        );
      }

      if (!data?.url) {
        throw new Error("No portal URL returned from server.");
      }

      return data.url as string;
    },
    onSuccess: (url) => {
      window.location.href = url;
    },
    onError: (error: unknown) => {
      const message =
        error instanceof Error ? error.message : "Failed to open portal.";
      toast.error(message);
    },
  });
}

// ── useUsage ─────────────────────────────────────────────────────
// Returns current scan usage derived from the authenticated user's profile.
// No network call — reads from AuthContext which is kept fresh.

export function useUsage() {
  const { profile } = useAuth();

  if (!profile) {
    return {
      scansUsed: 0,
      scanLimit: 0,
      usagePercent: 0,
      plan: "free" as PlanType,
      billingCycleEnd: null as string | null,
    };
  }

  const usagePercent =
    profile.scan_limit > 0
      ? Math.min((profile.scans_used / profile.scan_limit) * 100, 100)
      : 0;

  return {
    scansUsed: profile.scans_used,
    scanLimit: profile.scan_limit,
    usagePercent,
    plan: profile.plan,
    billingCycleEnd: profile.billing_cycle_end ?? null,
  };
}

