/**
 * stripe-webhook — Edge Function
 *
 * Handles incoming Stripe webhook events and keeps the profiles table
 * in sync with subscription state.
 *
 * Handled events:
 *   checkout.session.completed     → activate plan, set scan_limit, billing_cycle_end
 *   customer.subscription.updated  → sync plan changes (upgrade / downgrade)
 *   customer.subscription.deleted  → downgrade to free, clear billing data
 *   invoice.payment_failed         → log failure for observability
 *
 * Required env vars:
 *   STRIPE_SECRET_KEY
 *   STRIPE_WEBHOOK_SECRET          (from Stripe dashboard → webhook endpoint)
 *   SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 *
 * Security: Stripe-Signature header is verified before any processing.
 * No auth cookie / JWT required — Stripe calls this endpoint directly.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import Stripe from "https://esm.sh/stripe@14?target=deno";

// ── Plan config ───────────────────────────────────────────────────

type PlanType = "free" | "pro" | "agency";

const PLAN_LIMITS: Record<PlanType, number> = {
  free: 3,
  pro: 50,
  agency: 500,
};

// Derive plan from Stripe price IDs at runtime
function getPlanFromPriceId(priceId: string): PlanType {
  const proMonthly = Deno.env.get("STRIPE_PRICE_PRO_MONTHLY");
  const proAnnual = Deno.env.get("STRIPE_PRICE_PRO_ANNUAL");
  const agencyMonthly = Deno.env.get("STRIPE_PRICE_AGENCY_MONTHLY");
  const agencyAnnual = Deno.env.get("STRIPE_PRICE_AGENCY_ANNUAL");

  if (priceId === proMonthly || priceId === proAnnual) return "pro";
  if (priceId === agencyMonthly || priceId === agencyAnnual) return "agency";

  // Unknown price ID — default safe
  console.warn(`Unknown price ID: ${priceId}. Defaulting to 'pro'.`);
  return "pro";
}

// ── Serve ─────────────────────────────────────────────────────────

serve(async (req: Request) => {
  // Webhook endpoint does NOT handle CORS OPTIONS — Stripe never sends preflight.
  // Only POST requests arrive here.

  const signature = req.headers.get("stripe-signature");
  if (!signature) {
    return new Response(
      JSON.stringify({ error: "Missing Stripe-Signature header" }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  const webhookSecret = Deno.env.get("STRIPE_WEBHOOK_SECRET");
  if (!webhookSecret) {
    console.error("STRIPE_WEBHOOK_SECRET env var not set");
    return new Response(
      JSON.stringify({ error: "Webhook secret not configured" }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }

  const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY") ?? "", {
    apiVersion: "2024-06-20",
    httpClient: Stripe.createFetchHttpClient(),
  });

  // ── Verify signature ─────────────────────────────────────────────
  const body = await req.text();
  let event: Stripe.Event;

  try {
    event = await stripe.webhooks.constructEventAsync(body, signature, webhookSecret);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Invalid signature";
    console.error("Webhook signature verification failed:", message);
    return new Response(
      JSON.stringify({ error: `Webhook verification failed: ${message}` }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  // ── Admin Supabase client (bypasses RLS) ─────────────────────────
  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  // ── Event routing ─────────────────────────────────────────────────
  try {
    switch (event.type) {
      // ── checkout.session.completed ───────────────────────────────
      case "checkout.session.completed": {
        const session = event.data.object as Stripe.Checkout.Session;
        const userId = session.metadata?.user_id;
        const plan = (session.metadata?.plan ?? "pro") as PlanType;

        if (!userId) {
          console.error("checkout.session.completed: missing user_id in metadata");
          break;
        }

        // Fetch the created subscription to get billing period end
        let billingCycleEnd: string | null = null;
        if (session.subscription) {
          const subscription = await stripe.subscriptions.retrieve(
            session.subscription as string
          );
          billingCycleEnd = new Date(
            subscription.current_period_end * 1000
          ).toISOString();
        }

        const { error } = await supabase
          .from("profiles")
          .update({
            plan,
            scan_limit: PLAN_LIMITS[plan] ?? PLAN_LIMITS.pro,
            stripe_subscription_id: session.subscription ?? null,
            billing_cycle_end: billingCycleEnd,
            updated_at: new Date().toISOString(),
          })
          .eq("id", userId);

        if (error) {
          console.error("checkout.session.completed profile update error:", error);
        } else {
          console.log(`Activated ${plan} plan for user ${userId}`);
        }
        break;
      }

      // ── customer.subscription.updated ────────────────────────────
      case "customer.subscription.updated": {
        const subscription = event.data.object as Stripe.Subscription;

        // Find user by stripe_customer_id
        const { data: profile, error: profileError } = await supabase
          .from("profiles")
          .select("id, plan")
          .eq("stripe_customer_id", subscription.customer as string)
          .single();

        if (profileError || !profile) {
          console.error(
            "customer.subscription.updated: profile not found for customer",
            subscription.customer
          );
          break;
        }

        // Derive new plan from the subscription's first price item
        const priceId = subscription.items.data[0]?.price?.id;
        const newPlan: PlanType = priceId
          ? getPlanFromPriceId(priceId)
          : profile.plan;

        const billingCycleEnd = new Date(
          subscription.current_period_end * 1000
        ).toISOString();

        // Map subscription status to plan — cancelled/past_due → keep current until period end
        const isActive =
          subscription.status === "active" ||
          subscription.status === "trialing";

        const { error } = await supabase
          .from("profiles")
          .update({
            plan: isActive ? newPlan : profile.plan,
            scan_limit: isActive
              ? PLAN_LIMITS[newPlan] ?? PLAN_LIMITS.pro
              : PLAN_LIMITS[profile.plan as PlanType] ?? PLAN_LIMITS.free,
            stripe_subscription_id: subscription.id,
            billing_cycle_end: billingCycleEnd,
            updated_at: new Date().toISOString(),
          })
          .eq("id", profile.id);

        if (error) {
          console.error("customer.subscription.updated profile update error:", error);
        } else {
          console.log(
            `Updated subscription for user ${profile.id}: ${profile.plan} → ${newPlan} (status: ${subscription.status})`
          );
        }
        break;
      }

      // ── customer.subscription.deleted ────────────────────────────
      case "customer.subscription.deleted": {
        const subscription = event.data.object as Stripe.Subscription;

        const { data: profile, error: profileError } = await supabase
          .from("profiles")
          .select("id")
          .eq("stripe_customer_id", subscription.customer as string)
          .single();

        if (profileError || !profile) {
          console.error(
            "customer.subscription.deleted: profile not found for customer",
            subscription.customer
          );
          break;
        }

        const { error } = await supabase
          .from("profiles")
          .update({
            plan: "free",
            scan_limit: PLAN_LIMITS.free,
            stripe_subscription_id: null,
            billing_cycle_end: null,
            updated_at: new Date().toISOString(),
          })
          .eq("id", profile.id);

        if (error) {
          console.error("customer.subscription.deleted profile update error:", error);
        } else {
          console.log(`Downgraded user ${profile.id} to free plan (subscription deleted)`);
        }
        break;
      }

      // ── invoice.payment_failed ────────────────────────────────────
      case "invoice.payment_failed": {
        const invoice = event.data.object as Stripe.Invoice;
        console.log(
          `Payment failed for customer ${invoice.customer} — invoice ${invoice.id} — amount ${invoice.amount_due} ${invoice.currency}`
        );
        // Future: trigger a dunning email via send-email function
        break;
      }

      default:
        // Unhandled event type — acknowledge receipt to avoid retries
        console.log(`Unhandled webhook event type: ${event.type}`);
    }

    return new Response(
      JSON.stringify({ received: true }),
      { status: 200, headers: { "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Handler error";
    console.error(`Error handling ${event.type}:`, error);
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }
});

