/**
 * dodo-checkout — Edge Function
 *
 * Creates a Dodo Payments subscription checkout session for plan upgrades.
 *
 * Expected request body:
 *   { plan: 'pro' | 'agency'; billing_cycle: 'monthly' | 'annual' }
 *
 * Returns:
 *   { url: string } — Dodo-hosted checkout page URL
 *
 * Required env vars:
 *   DODO_API_KEY
 *   DODO_PRODUCT_PRO_MONTHLY
 *   DODO_PRODUCT_PRO_ANNUAL
 *   DODO_PRODUCT_AGENCY_MONTHLY
 *   DODO_PRODUCT_AGENCY_ANNUAL
 *   SITE_URL
 *   SUPABASE_URL
 *   SUPABASE_ANON_KEY
 *   SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

function getProductId(plan: string, billingCycle: string): string | null {
  const map: Record<string, string> = {
    "pro:monthly": Deno.env.get("DODO_PRODUCT_PRO_MONTHLY") ?? "",
    "pro:annual": Deno.env.get("DODO_PRODUCT_PRO_ANNUAL") ?? "",
    "agency:monthly": Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY") ?? "",
    "agency:annual": Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL") ?? "",
  };
  return map[`${plan}:${billingCycle}`] || null;
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // ── 1. Auth ──────────────────────────────────────────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Missing Authorization header" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const supabaseUser = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
      { global: { headers: { Authorization: authHeader } } }
    );

    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !user) {
      return new Response(
        JSON.stringify({ error: "Unauthorized" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 2. Parse + validate body ─────────────────────────────────────
    let body: { plan?: string; billing_cycle?: string };
    try {
      body = await req.json();
    } catch {
      return new Response(
        JSON.stringify({ error: "Invalid JSON body" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const { plan, billing_cycle } = body;

    if (!plan || !["pro", "agency"].includes(plan)) {
      return new Response(
        JSON.stringify({ error: "Invalid plan. Must be 'pro' or 'agency'." }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    if (!billing_cycle || !["monthly", "annual"].includes(billing_cycle)) {
      return new Response(
        JSON.stringify({ error: "Invalid billing_cycle. Must be 'monthly' or 'annual'." }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const productId = getProductId(plan, billing_cycle);
    if (!productId) {
      console.error(`Missing product ID for ${plan}:${billing_cycle}`);
      return new Response(
        JSON.stringify({ error: "Pricing configuration error. Contact support." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 3. Get user profile ──────────────────────────────────────────
    const supabaseAdmin = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    const { data: profile, error: profileError } = await supabaseAdmin
      .from("profiles")
      .select("id, email, full_name, dodo_customer_id")
      .eq("id", user.id)
      .single();

    if (profileError || !profile) {
      console.error("Profile fetch error:", profileError);
      return new Response(
        JSON.stringify({ error: "User profile not found." }),
        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 4. Build Dodo customer payload ───────────────────────────────
    const customerPayload = profile.dodo_customer_id
      ? { create_new_customer: false, customer_id: profile.dodo_customer_id }
      : {
          create_new_customer: true,
          email: profile.email ?? user.email,
          name: profile.full_name ?? "",
        };

    const origin = Deno.env.get("SITE_URL") ?? "http://localhost:5173";
    const dodoApiKey = Deno.env.get("DODO_API_KEY") ?? "";

    // ── 5. Create subscription checkout with payment link ────────────
    const dodoRes = await fetch("https://api.dodopayments.com/subscriptions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${dodoApiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        billing: {
          currency: "USD",
          interval: billing_cycle === "annual" ? "year" : "month",
          interval_count: 1,
        },
        customer: customerPayload,
        product_id: productId,
        payment_link: true,
        return_url: `${origin}/dashboard?checkout=success`,
        metadata: {
          user_id: user.id,
          plan,
        },
      }),
    });

    if (!dodoRes.ok) {
      const errText = await dodoRes.text();
      console.error("Dodo API error:", dodoRes.status, errText);
      return new Response(
        JSON.stringify({ error: "Failed to create checkout session." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const dodoData = await dodoRes.json();

    // Persist customer ID if newly created
    if (!profile.dodo_customer_id && dodoData.customer_id) {
      const { error: updateError } = await supabaseAdmin
        .from("profiles")
        .update({ dodo_customer_id: dodoData.customer_id })
        .eq("id", user.id);

      if (updateError) {
        // Non-fatal — will be captured via webhook
        console.error("Failed to persist dodo_customer_id:", updateError);
      }
    }

    const checkoutUrl = dodoData.payment_link;
    if (!checkoutUrl) {
      console.error("No payment_link in Dodo response:", dodoData);
      return new Response(
        JSON.stringify({ error: "No checkout URL returned from payment provider." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    return new Response(
      JSON.stringify({ url: checkoutUrl }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Internal server error";
    console.error("dodo-checkout error:", error);
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

