    const wh = new Webhook(webhookSecret);
    const headers = {
      "webhook-id": req.headers.get("webhook-id") ?? "",
      "webhook-timestamp": req.headers.get("webhook-timestamp") ?? "",
      "webhook-signature": req.headers.get("webhook-signature") ?? "",
    };
    event = wh.verify(body, headers) as { type: string; data: Record<string, unknown> };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Invalid signature";
    console.error("Webhook signature verification failed:", message);
    return new Response(
      JSON.stringify({ error: `Webhook verification failed: ${message}` }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  // ── Admin Supabase client (bypasses RLS) ─────────────────────────
  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  // ── Event routing ─────────────────────────────────────────────────
  try {
    switch (event.type) {
      // ── subscription.active ──────────────────────────────────────
      // Fires when a new subscription is created and payment succeeds.
      case "subscription.active": {
        const sub = event.data as {
          subscription_id: string;
          customer_id: string;
          product_id: string;
          current_period_end?: number;
          metadata?: Record<string, string>;
        };

        const userId = sub.metadata?.user_id;
        const plan = (sub.metadata?.plan ?? getPlanFromProductId(sub.product_id)) as PlanType;

