          console.error("subscription.active: missing user_id in metadata");
          break;
        }

        const billingCycleEnd = sub.current_period_end
          ? new Date(sub.current_period_end * 1000).toISOString()
          : null;

        const { error } = await supabase
          .from("profiles")
          .update({
            plan,
            scan_limit: PLAN_LIMITS[plan] ?? PLAN_LIMITS.pro,
            dodo_subscription_id: sub.subscription_id,
            dodo_customer_id: sub.customer_id,
            billing_cycle_end: billingCycleEnd,
            updated_at: new Date().toISOString(),
