import { useState } from "react";
import {
  CreditCard,
  Zap,
  Gauge,
  Camera,
  Mail,
  Database,
  ExternalLink,
  ChevronDown,
  CheckCircle2,
  XCircle,
  AlertCircle,
  Lock,
  FlaskConical,
  Loader2,
  Info,
} from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
