    ],
    externalUrl: "https://dashboard.dodopayments.com",
    externalLabel: "Dodo Dashboard",
  },
  {
    id: "anthropic",
    name: "Anthropic Claude API",
    subtitle: "claude-sonnet-4-20250514 · Vision + Text analysis",
    category: "AI Engine",
    description:
      "Powers all 7 CRO pillar analyses using Vision (screenshot) + Text, generating scored findings and AI rewrite suggestions for every scan.",
    status: "server-side",
    icon: Zap,
    iconBg: "bg-purple-500/10",

    ],
    usedBy: ["analyze-url", "pagespeed", "stripe-checkout", "stripe-webhook", "send-email"],
    setupSteps: [
      { n: 1, text: <>Create a project at <a href="https://supabase.com/dashboard" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">supabase.com/dashboard</a></> },
      { n: 2, text: <>Copy Project URL and anon key from <strong>Project Settings → API</strong> into your <code className="bg-background border border-border/60 px-1 py-0.5 rounded text-xs font-mono">.env.local</code></> },
      { n: 3, text: "Run all database migrations via the Supabase CLI: npx supabase db push" },
