                          </code>{" "}
                          RPC and set every user's scan count back to 0. This
                          cannot be undone.
                        </AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                          onClick={() => resetScans.mutate()}
                          className="bg-amber-600 hover:bg-amber-700"
                        >
                          Reset All
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>

                {/* Clear failed scans */}
                <div className="rounded-lg border border-border/50 p-4 space-y-2">
                  <div className="flex items-center gap-2">
                    <Trash2 className="h-4 w-4 text-red-500" />
                    <p className="text-sm font-medium">Clear Old Failed Scans</p>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Permanently deletes scans with{" "}
                    <code className="font-mono text-xs bg-muted/50 px-1 py-0.5 rounded">
                      status = failed
                    </code>{" "}
                    older than 30 days. Frees up storage and cleans up the scan
                    table.
                  </p>
                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button
                        variant="outline"
                        size="sm"
                        className="w-full mt-1 border-red-200 hover:bg-red-50 hover:border-red-300 text-red-600"
                        disabled={clearFailed.isPending}
                      >
                        {clearFailed.isPending ? (
                          <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <Trash2 className="mr-2 h-3.5 w-3.5" />
                        )}
                        {clearFailed.isPending ? "Clearing…" : "Clear Failed Scans"}
                      </Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>
                          Clear old failed scans?
                        </AlertDialogTitle>
                        <AlertDialogDescription>
                          This will permanently delete all failed scans older
                          than 30 days, including their associated results. This
                          cannot be undone.
                        </AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                          onClick={() => clearFailed.mutate()}
                          className="bg-destructive hover:bg-destructive/90"
                        >
                          Delete Old Scans
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>

                {/* Quick wins notice */}
                <div className="rounded-lg border border-dashed border-border/50 px-4 py-3">
                  <div className="flex items-center gap-2">
                    <Zap className="h-3.5 w-3.5 text-muted-foreground/60" />
                    <p className="text-xs text-muted-foreground">
                      More system actions will be added here as the platform
                      grows.
                    </p>
                  </div>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
